*.tfplan
crash.log
crash.*.log
*.auto.tfvars
terraform.tfvars
EOF
cp versions.tf bootstrap/versions.tf
cat > bootstrap/providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
