variable "region" {
  type        = string
  description = "AWS region the state bucket is created in."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose one unique to your organization."

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name))
    error_message = "Use 3-63 characters: lowercase letters, digits, hyphens and dots, starting and ending with a letter or digit."
  }
}

variable "noncurrent_version_retention_days" {
  type        = number
  description = "Days a replaced or deleted state version is kept before S3 removes it. Older versions cannot be rolled back to."
  default     = 90
}
EOF
cat > bootstrap/main.tf <<'EOF'
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  # Versioning must exist before a noncurrent-version rule is accepted.
  depends_on = [aws_s3_bucket_versioning.state]

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > bootstrap/outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket. Put it in the bucket setting of the backend config of each configuration that stores state here."
  value       = aws_s3_bucket.state.id
}

output "state_bucket_region" {
  description = "Region of the state bucket."
  value       = var.region
}
EOF
# root backend
cat >> versions.tf <<'EOF'
EOF
python3 - <<'EOF'
p='versions.tf'
s=open(p).read()
s=s.replace('  required_version = ">= 1.10.0"\n','  required_version = ">= 1.10.0"\n\n  # Bucket comes from backend.hcl: terraform init -backend-config=backend.hcl\n  backend "s3" {\n    key          = "reports/terraform.tfstate"\n    region       = "eu-north-1"\n    encrypt      = true\n    use_lockfile = true\n  }\n')
open(p,'w').write(s)
EOF
cat > backend.hcl <<'EOF'
# Non-secret backend metadata. Set this to the bucket created by bootstrap/.
bucket = "example-org-reports-tfstate"
EOF
terraform fmt -recursive -check -diff; for d in . bootstrap; do (cd $d && terraform init -backend=false -input=false >/dev/null && terraform validate); done; checkov -d . --quiet --compact 2>&1 | tail -40

